import React, { useState, useEffect, useRef, useCallback } from 'react';

const ARVR = () => {
  const [selectedLocation, setSelectedLocation] = useState('Betla National Park');
  const [previewUrl, setPreviewUrl] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [previewError, setPreviewError] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showInfo, setShowInfo] = useState(true);
  const [viewMode, setViewMode] = useState('360'); // 360, VR, AR
  const [zoomLevel, setZoomLevel] = useState(1);
  const [showHotspots, setShowHotspots] = useState(true);
  const [currentHotspot, setCurrentHotspot] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioEnabled, setAudioEnabled] = useState(false);
  const [showTutorial, setShowTutorial] = useState(true);

  // Fixed image URLs - using http instead of https to avoid certificate issues
  const locationMap = {
    'Betla National Park': {
      url: 'https://arvr.jharkhandtourism.com/betla',
      description: 'Explore the wilderness of Betla National Park, home to tigers, elephants, and diverse flora. Experience the jungle trails and historic ruins in immersive 360°.',
      image: 'https://source.unsplash.com/photo-1599316148061-5d5d37b52336',
      hotspots: [
        { id: 1, x: 30, y: 40, title: 'Jungle Trail', description: 'Explore the dense forest pathways' },
        { id: 2, x: 60, y: 25, title: 'Historic Ruins', description: 'Discover ancient structures' },
        { id: 3, x: 70, y: 60, title: 'Watch Tower', description: 'Panoramic views of the park' }
      ]
    },
    'Hundru Falls': {
      url: 'https://arvr.jharkhandtourism.com/hundru',
      description: 'Witness the majestic Hundru Falls, one of the highest waterfalls in Jharkhand. Experience the thunderous water cascade from multiple vantage points.',
      image: 'https://source.unsplash.com/photo-1696252189917-68d74e28acd1',
      hotspots: [
        { id: 1, x: 50, y: 30, title: 'Top View', description: 'See the waterfall from above' },
        { id: 2, x: 25, y: 60, title: 'Base Camp', description: 'Feel the mist on your face' },
        { id: 3, x: 75, y: 70, title: 'Viewpoint', description: 'Perfect photo opportunity' }
      ]
    },
    'Jonha Falls': {
      url: 'https://arvr.jharkhandtourism.com/jonha',
      description: 'Discover Jonha Falls, also known as Gautamdhara Falls. Enjoy the serene surroundings and the beautiful waterfall in this immersive experience.',
      image: 'https://source.unsplash.com/photo-1509316975850-57b4bbce2410',
      hotspots: [
        { id: 1, x: 40, y: 50, title: 'Main Falls', description: 'The primary waterfall view' },
        { id: 2, x: 60, y: 30, title: 'Rock Formations', description: 'Unique geological features' },
        { id: 3, x: 20, y: 70, title: 'Bridge View', description: 'Scenic overlook from the bridge' }
      ]
    },
    'Baidyanath Dham': {
      url: 'https://arvr.jharkhandtourism.com/baidyanath',
      description: 'Experience the spiritual aura of Baidyanath Dham, one of the twelve Jyotirlingas. Virtually explore the temple complex and its sacred surroundings.',
      image: 'https://source.unsplash.com/photo-1589098614514-e1ae9c8d2a64',
      hotspots: [
        { id: 1, x: 50, y: 40, title: 'Main Temple', description: 'The sacred Jyotirlinga shrine' },
        { id: 2, x: 30, y: 60, title: 'Prayer Hall', description: 'Space for devotional activities' },
        { id: 3, x: 70, y: 20, title: 'Temple Complex', description: 'Overview of the entire area' }
      ]
    },
    'Patratu Valley': {
      url: 'https://arvr.jharkhandtourism.com/patratu',
      description: 'Take in the breathtaking views of Patratu Valley with its serpentine roads and lush green landscapes. Experience this engineering marvel in 360°.',
      image: 'https://source.unsplash.com/photo-1506905925346-21bda4d32df4',
      hotspots: [
        { id: 1, x: 40, y: 30, title: 'Valley Overview', description: 'Panoramic view of the valley' },
        { id: 2, x: 60, y: 50, title: 'Serpentine Road', description: 'The famous winding road' },
        { id: 3, x: 20, y: 70, title: 'Viewpoint', description: 'Best spot for photography' }
      ]
    },
  };

  const handleShowPreview = () => {
    const url = locationMap[selectedLocation].url;
    setPreviewUrl(url);
    setIsLoading(true);
    setPreviewError(false);
    
    // Simulate loading
    setTimeout(() => {
      setIsLoading(false);
      setIsPlaying(true);
    }, 2000);
  };

  const handleRetry = () => {
    setIsLoading(true);
    setPreviewError(false);
    // Simulate loading
    setTimeout(() => {
      setIsLoading(false);
      setIsPlaying(true);
    }, 2000);
  };

  const toggleFullscreen = () => {
    setIsFullscreen(!isFullscreen);
  };

  const toggleInfo = () => {
    setShowInfo(!showInfo);
  };

  const toggleAudio = () => {
    setAudioEnabled(!audioEnabled);
  };

  const changeViewMode = (mode) => {
    setViewMode(mode);
    if (mode === 'VR') {
      // Simulate VR mode activation
      setTimeout(() => {
        alert('VR mode would activate your headset in a real implementation');
      }, 300);
    }
  };

  const handleZoomIn = () => {
    setZoomLevel(prev => Math.min(prev + 0.2, 2));
  };

  const handleZoomOut = () => {
    setZoomLevel(prev => Math.max(prev - 0.2, 0.5));
  };

  const resetView = () => {
    setZoomLevel(1);
  };

  const toggleTutorial = () => {
    setShowTutorial(!showTutorial);
  };

  // Simulate AR/VR experience with interactive 360° viewer
  const InteractiveViewer = () => {
    const [rotation, setRotation] = useState({ x: 0, y: 0 });
    const [isDragging, setIsDragging] = useState(false);
    const [startPosition, setStartPosition] = useState({ x: 0, y: 0 });
    const viewerRef = useRef(null);

    // Use useCallback to prevent recreation of functions on every render
    const handleMouseDown = useCallback((e) => {
      setIsDragging(true);
      setStartPosition({ x: e.clientX, y: e.clientY });
    }, []);

    const handleTouchStart = useCallback((e) => {
      setIsDragging(true);
      setStartPosition({ x: e.touches[0].clientX, y: e.touches[0].clientY });
    }, []);

    const handleMouseMove = useCallback((e) => {
      if (!isDragging) return;
      
      const deltaX = e.clientX - startPosition.x;
      const deltaY = e.clientY - startPosition.y;
      
      setRotation(prev => ({
        x: Math.max(-90, Math.min(90, prev.x + deltaY * 0.5)),
        y: prev.y + deltaX * 0.5
      }));
      
      setStartPosition({ x: e.clientX, y: e.clientY });
    }, [isDragging, startPosition]);

    const handleTouchMove = useCallback((e) => {
      if (!isDragging) return;
      
      const deltaX = e.touches[0].clientX - startPosition.x;
      const deltaY = e.touches[0].clientY - startPosition.y;
      
      setRotation(prev => ({
        x: Math.max(-90, Math.min(90, prev.x + deltaY * 0.5)),
        y: prev.y + deltaX * 0.5
      }));
      
      setStartPosition({ x: e.touches[0].clientX, y: e.touches[0].clientY });
    }, [isDragging, startPosition]);

    const handleMouseUp = useCallback(() => {
      setIsDragging(false);
    }, []);

    const handleTouchEnd = useCallback(() => {
      setIsDragging(false);
    }, []);

    const handleHotspotClick = useCallback((hotspot, e) => {
      e.stopPropagation();
      setCurrentHotspot(hotspot);
      setTimeout(() => {
        setCurrentHotspot(null);
      }, 4000);
    }, []);

    // Mouse and touch event listeners
    useEffect(() => {
      if (isDragging) {
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        window.addEventListener('touchmove', handleTouchMove);
        window.addEventListener('touchend', handleTouchEnd);
        
        return () => {
          window.removeEventListener('mousemove', handleMouseMove);
          window.removeEventListener('mouseup', handleMouseUp);
          window.removeEventListener('touchmove', handleTouchMove);
          window.removeEventListener('touchend', handleTouchEnd);
        };
      }
    }, [isDragging, handleMouseMove, handleMouseUp, handleTouchMove, handleTouchEnd]);

    // Keyboard navigation
    useEffect(() => {
      const handleKeyDown = (e) => {
        if (!isPlaying) return;
        
        switch(e.key) {
          case 'ArrowUp':
            setRotation(prev => ({ ...prev, x: Math.max(-90, prev.x - 5) }));
            break;
          case 'ArrowDown':
            setRotation(prev => ({ ...prev, x: Math.min(90, prev.x + 5) }));
            break;
          case 'ArrowLeft':
            setRotation(prev => ({ ...prev, y: prev.y - 5 }));
            break;
          case 'ArrowRight':
            setRotation(prev => ({ ...prev, y: prev.y + 5 }));
            break;
          case '+':
            handleZoomIn();
            break;
          case '-':
            handleZoomOut();
            break;
          case '0':
            resetView();
            break;
          case 'Escape':
            if (isFullscreen) setIsFullscreen(false);
            if (currentHotspot) setCurrentHotspot(null);
            break;
          default:
            break;
        }
      };

      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isPlaying, isFullscreen, currentHotspot]);

    return (
      <div 
        ref={viewerRef}
        className={`relative bg-gray-900 overflow-hidden ${isFullscreen ? 'fixed inset-0 z-50 h-screen' : 'h-96 rounded-lg'}`}
        onMouseDown={handleMouseDown}
        onTouchStart={handleTouchStart}
        style={{ cursor: isDragging ? 'grabbing' : 'grab' }}
      >
        <div 
          className="absolute inset-0 bg-cover bg-center"
          style={{ 
            backgroundImage: `url(${locationMap[selectedLocation].image})`,
            transform: `rotateX(${rotation.x}deg) rotateY(${rotation.y}deg) scale(${zoomLevel})`,
            transition: isDragging ? 'none' : 'transform 0.1s ease',
            filter: viewMode === 'AR' ? 'sepia(0.5) saturate(1.5)' : 'none'
          }}
        />
        
        {/* Hotspots */}
        {showHotspots && locationMap[selectedLocation].hotspots.map(hotspot => (
          <div
            key={hotspot.id}
            className="absolute w-6 h-6 rounded-full bg-red-500 bg-opacity-70 border-2 border-white cursor-pointer transform -translate-x-1/2 -translate-y-1/2 flex items-center justify-center animate-pulse"
            style={{ left: `${hotspot.x}%`, top: `${hotspot.y}%` }}
            onClick={(e) => handleHotspotClick(hotspot, e)}
            title={hotspot.title}
          >
            <span className="text-white text-xs">●</span>
          </div>
        ))}
        
        {/* Current Hotspot Info */}
        {currentHotspot && (
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-black bg-opacity-80 text-white p-4 rounded-lg max-w-xs z-10"
               style={{ animation: 'fadeIn 0.3s ease-in-out' }}>
            <h4 className="font-bold text-lg mb-2">{currentHotspot.title}</h4>
            <p className="text-sm">{currentHotspot.description}</p>
            <button 
              className="absolute top-2 right-2 text-white"
              onClick={() => setCurrentHotspot(null)}
            >
              ✕
            </button>
          </div>
        )}
        
        <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 bg-black bg-opacity-50 text-white px-4 py-2 rounded-lg flex items-center space-x-4">
          <p className="text-sm">Drag to look around</p>
          <div className="w-1 h-1 bg-white rounded-full"></div>
          <p className="text-sm">Scroll to zoom</p>
          <div className="w-1 h-1 bg-white rounded-full"></div>
          <p className="text-sm">Click hotspots for info</p>
        </div>
        
        <div className="absolute top-4 right-4 flex space-x-2">
          <button 
            onClick={toggleInfo}
            className="bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-70 transition"
            title="Toggle information"
          >
            ⓘ
          </button>
          <button 
            onClick={() => setShowHotspots(!showHotspots)}
            className="bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-70 transition"
            title={showHotspots ? 'Hide hotspots' : 'Show hotspots'}
          >
            🔍
          </button>
          <button 
            onClick={toggleAudio}
            className={`bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-70 transition ${audioEnabled ? 'text-yellow-400' : ''}`}
            title={audioEnabled ? 'Mute audio' : 'Enable audio'}
          >
            {audioEnabled ? '🔊' : '🔈'}
          </button>
          <button 
            onClick={toggleFullscreen}
            className="bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-70 transition"
            title={isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}
          >
            {isFullscreen ? '⇲' : '⇱'}
          </button>
          {isFullscreen && (
            <button 
              onClick={() => setIsFullscreen(false)}
              className="bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-70 transition"
              title="Close"
            >
              ✕
            </button>
          )}
        </div>
        
        {showInfo && (
          <div className="absolute top-4 left-4 bg-black bg-opacity-70 text-white p-4 rounded-lg max-w-xs backdrop-blur-sm">
            <h4 className="font-bold text-lg mb-2">{selectedLocation}</h4>
            <p className="text-sm mb-2">{locationMap[selectedLocation].description}</p>
            <div className="flex space-x-2 mt-2">
              <button 
                className={`px-2 py-1 rounded text-xs ${viewMode === '360' ? 'bg-blue-600' : 'bg-gray-700'}`}
                onClick={() => changeViewMode('360')}
              >
                360°
              </button>
              <button 
                className={`px-2 py-1 rounded text-xs ${viewMode === 'VR' ? 'bg-blue-600' : 'bg-gray-700'}`}
                onClick={() => changeViewMode('VR')}
              >
                VR
              </button>
              <button 
                className={`px-2 py-1 rounded text-xs ${viewMode === 'AR' ? 'bg-blue-600' : 'bg-gray-700'}`}
                onClick={() => changeViewMode('AR')}
              >
                AR
              </button>
            </div>
          </div>
        )}
        
        <div className="absolute bottom-4 right-4 bg-black bg-opacity-50 text-white p-2 rounded-lg flex flex-col space-y-2">
          <button className="p-2 hover:bg-opacity-20 hover:bg-white rounded" title="Move forward" onClick={() => setRotation(prev => ({...prev, x: Math.max(-90, prev.x - 10)}))}>↑</button>
          <div className="flex space-x-2">
            <button className="p-2 hover:bg-opacity-20 hover:bg-white rounded" title="Move left" onClick={() => setRotation(prev => ({...prev, y: prev.y - 10}))}>←</button>
            <button className="p-2 hover:bg-opacity-20 hover:bg-white rounded" title="Move backward" onClick={() => setRotation(prev => ({...prev, x: Math.min(90, prev.x + 10)}))}>↓</button>
            <button className="p-2 hover:bg-opacity-20 hover:bg-white rounded" title="Move right" onClick={() => setRotation(prev => ({...prev, y: prev.y + 10}))}>→</button>
          </div>
        </div>
        
        <div className="absolute left-4 bottom-4 bg-black bg-opacity-50 text-white p-2 rounded-lg flex flex-col space-y-2">
          <button className="p-2 hover:bg-opacity-20 hover:bg-white rounded" title="Zoom in" onClick={handleZoomIn}>+</button>
          <button className="p-2 hover:bg-opacity-20 hover:bg-white rounded" title="Reset view" onClick={resetView}>⟳</button>
          <button className="p-2 hover:bg-opacity-20 hover:bg-white rounded" title="Zoom out" onClick={handleZoomOut}>-</button>
        </div>
        
        {viewMode === 'VR' && (
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <div className="w-1/2 h-full border-l-2 border-r-2 border-white border-opacity-20"></div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className={`p-6 bg-gradient-to-br from-blue-50 to-green-50 min-h-screen ${isFullscreen ? 'pt-20' : ''}`}>
      {!isFullscreen && (
        <>
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-3xl font-bold text-gray-800">Jharkhand AR/VR Experience</h2>
            <button 
              onClick={toggleTutorial}
              className="bg-blue-100 text-blue-700 px-3 py-1 rounded-lg text-sm hover:bg-blue-200 transition"
            >
              {showTutorial ? 'Hide Tips' : 'Show Tips'}
            </button>
          </div>
          
          {showTutorial && (
            <div className="mb-6 bg-blue-50 border border-blue-200 rounded-lg p-4">
              <h3 className="font-bold text-blue-800 mb-2">💡 Pro Tip:</h3>
              <p className="text-blue-700">Use keyboard arrows to navigate, +/- to zoom, and 0 to reset view. Click on the glowing dots to discover points of interest!</p>
            </div>
          )}
          
          <div className="mb-6 bg-white rounded-lg shadow-md p-4">
            <div className="flex flex-col md:flex-row md:items-center gap-4">
              <select
                value={selectedLocation}
                onChange={(e) => setSelectedLocation(e.target.value)}
                className="p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent flex-grow"
              >
                {Object.keys(locationMap).map((location) => (
                  <option key={location} value={location}>
                    {location}
                  </option>
                ))}
              </select>

              <button 
                onClick={handleShowPreview} 
                className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-lg font-medium transition-colors shadow-md flex items-center justify-center"
              >
                <span className="mr-2">🚀</span> Start Experience
              </button>
            </div>
            
            <p className="mt-4 text-gray-600">
              🌳 Explore <strong className="text-green-700">{selectedLocation}</strong> in immersive 360° views. 
              This AR/VR experience lets you virtually walk through forest trails, spot wildlife, and discover hidden gems of Jharkhand.
            </p>
          </div>
        </>
      )}

      <div className={`${isFullscreen ? '' : 'mt-6'}`}>
        {!isFullscreen && (
          <h3 className="text-xl font-bold mb-4 text-gray-700">Interactive Preview</h3>
        )}

        {isLoading ? (
          <div className="h-96 bg-gray-100 rounded-lg flex flex-col items-center justify-center relative overflow-hidden">
            <div className="absolute inset-0 bg-gradient-to-r from-blue-400 to-green-400 opacity-10 animate-pulse"></div>
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mb-4 z-10"></div>
            <p className="text-gray-600 z-10">Loading {selectedLocation} experience...</p>
            <p className="text-sm text-gray-500 mt-2 z-10">Preparing immersive environment</p>
            <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 text-xs text-gray-500">
              Tip: Use fullscreen for the best experience
            </div>
          </div>
        ) : previewError ? (
          <div className="h-96 bg-gray-100 rounded-lg flex flex-col items-center justify-center p-4">
            <div className="text-red-500 text-5xl mb-4">⚠️</div>
            <p className="text-red-500 text-lg mb-4 text-center">Sorry, the AR/VR preview is currently unavailable.</p>
            <button 
              onClick={handleRetry} 
              className="bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-lg flex items-center transition-colors"
            >
              <span className="mr-2">🔄</span> Retry Preview
            </button>
            <p className="text-gray-500 text-sm mt-4">If the problem persists, try again later</p>
          </div>
        ) : previewUrl ? (
          <InteractiveViewer />
        ) : (
          <div className="h-96 bg-gradient-to-r from-blue-100 to-green-100 rounded-lg flex flex-col items-center justify-center p-6 text-center relative overflow-hidden">
            <div 
              className="absolute inset-0 opacity-10"
              style={{
                backgroundImage: 'radial-gradient(circle, #00000010 1px, transparent 1px)',
                backgroundSize: '20px 20px'
              }}
            ></div>
            <div 
              className="text-5xl mb-4"
              style={{ animation: 'float 3s ease-in-out infinite' }}
            >
              🌄
            </div>
            <h3 className="text-2xl font-bold text-gray-700 mb-2">Discover Jharkhand in VR</h3>
            <p className="text-gray-600 max-w-md mb-6">
              Select a location and click "Start Experience" to begin your virtual journey through Jharkhand's most beautiful destinations.
            </p>
            <div className="flex space-x-2">
              <div className="w-3 h-3 bg-blue-400 rounded-full animate-bounce"></div>
              <div className="w-3 h-3 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
              <div className="w-3 h-3 bg-blue-400 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></div>
            </div>
          </div>
        )}
      </div>

      {!isFullscreen && (
        <div className="mt-8 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          <div className="bg-white p-4 rounded-lg shadow-md">
            <h4 className="font-bold text-lg mb-2 text-gray-800 flex items-center">🎮 How to Navigate</h4>
            <ul className="text-sm text-gray-600 space-y-1">
              <li className="flex items-center"><span className="mr-2">↔️</span> Drag to look around in 360°</li>
              <li className="flex items-center"><span className="mr-2">⬆️⬇️</span> Use arrow keys/buttons to move</li>
              <li className="flex items-center"><span className="mr-2">🔍</span> Click hotspots for information</li>
              <li className="flex items-center"><span className="mr-2">🔊</span> Enable audio for immersion</li>
            </ul>
          </div>
          
          <div className="bg-white p-4 rounded-lg shadow-md">
            <h4 className="font-bold text-lg mb-2 text-gray-800 flex items-center">📱 Device Support</h4>
            <ul className="text-sm text-gray-600 space-y-1">
              <li className="flex items-center"><span className="mr-2">💻</span> Desktop: Mouse and keyboard</li>
              <li className="flex items-center"><span className="mr-2">📱</span> Mobile: Touch gestures</li>
              <li className="flex items-center"><span className="mr-2">🥽</span> VR Headsets: Full immersion</li>
              <li className="flex items-center"><span className="mr-2">🔊</span> Spatial audio supported</li>
            </ul>
          </div>
          
          <div className="bg-white p-4 rounded-lg shadow-md">
            <h4 className="font-bold text-lg mb-2 text-gray-800 flex items-center">ℹ️ Tips</h4>
            <ul className="text-sm text-gray-600 space-y-1">
              <li className="flex items-center"><span className="mr-2">🎧</span> Use headphones for spatial audio</li>
              <li className="flex items-center"><span className="mr-2">🚀</span> Strong internet recommended</li>
              <li className="flex items-center"><span className="mr-2">📳</span> Allow motion sensors on mobile</li>
              <li className="flex items-center"><span className="mr-2">🔲</span> Fullscreen for best experience</li>
            </ul>
          </div>
        </div>
      )}
      
      {/* Add CSS animations to your global CSS file or use inline styles */}
      <style>{`
        @keyframes float {
          0% { transform: translateY(0px); }
          50% { transform: translateY(-10px); }
          100% { transform: translateY(0px); }
        }
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
      `}</style>
    </div>
  );
};

export default ARVR;
